def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 100 or opp.get('budget', 0) > 400:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / WATER_REQ
    contested = units < (1 + len(alive_opponents))
    very_tight = supply <= 16
    loose = supply >= 22

    if hp <= 2 or no_water >= 2:
        emergency = max(62.0, min(0.92 * DAILY_SALARY, highest_prev * 0.72 + 8.0))
        return float(min(budget, emergency))

    if hp <= 4 or no_water >= 1:
        if very_tight:
            bid = max(48.0, min(61.0, highest_prev * 0.45 + 6.0))
        elif contested:
            bid = max(38.0, min(52.0, avg_prev * 0.32 + 7.0))
        else:
            bid = 26.0
        return float(min(budget, bid))

    if loose and rich_aggressive >= 2:
        return float(min(budget, 9.0))

    if very_tight:
        bid = 24.0 if day < 7 else 30.0
    elif contested:
        bid = 16.0 if rich_aggressive >= 1 else 22.0
    else:
        bid = 11.0

    if highest_prev < 40 and contested:
        bid = max(bid, highest_prev + 2.0)

    bid = min(bid, budget)
    if budget < 15:
        bid = min(bid, max(0.0, budget))

    return float(max(0.0, bid))

