def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Use only yesterday trace bids for immediate reaction
    prev_bids = []
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # If we don't have trace bids, fall back to hp-based
    if not prev_bids:
        if hp <= 2 or no_water_days >= 2:
            return max(0.0, min(budget, DAILY_SALARY * 0.9))
        return max(0.0, min(budget, DAILY_SALARY * 0.55))

    highest_prev_bid = max(prev_bids)
    avg_prev_bid = sum(prev_bids) / float(len(prev_bids))

    # Estimate competition pressure: yesterday had strong surviving bids around ~114-140.
    # Target a bid slightly above yesterday average when my hp is healthy.
    # If my hp is low, bid more aggressively to avoid running out.
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = avg_prev_bid / highest_prev_bid

    # Baseline target
    if highest_prev_bid >= DAILY_SALARY * 0.8:
        # Very strong competition: try to match/beat the high bids
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        elif hp <= 4:
            target = DAILY_SALARY * 0.75
        else:
            target = min(DAILY_SALARY * 0.85, highest_prev_bid + 10.0)
    else:
        # Moderate competition: bid around average/upper-mid
        if hp <= 2 or no_water_days >= 2:
            target = max(highest_prev_bid, avg_prev_bid) + 5.0
        elif hp <= 4:
            target = max(highest_prev_bid * 0.9, avg_prev_bid) + 2.0
        else:
            target = max(avg_prev_bid, highest_prev_bid * 0.75) + 1.5

    # Supply-aware adjustment: higher supply means less need to overbid
    # Normalize supply to [0,1]
    supply_norm = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_norm = 0.0 if supply_norm < 0.0 else (1.0 if supply_norm > 1.0 else supply_norm)

    # If supply is low, slightly increase bid; if high, slightly decrease
    target *= (1.08 - 0.16 * supply_norm)

    # Ensure we don't bid more than budget
    bid = max(0.0, min(budget, target))

    # If budget is extremely low, still bid something small to avoid zero-water streak
    if bid <= 0.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * 0.1)

    return float(bid)
